/**
 * diagnosis/intent-alignment.ts — 意图对齐度
 *
 * 测量三层对齐偏差：人-组织、Agent-组织、人-Agent。
 *
 * PRIMARY (v1.0): SOG Goal 节点 + ALIGNS_WITH 边 —— 图结构驱动，精确计算
 * FALLBACK (legacy): 文本关键词重叠 —— 保留用于无 SOG 场景的向后兼容
 *
 * 纯计算模块：消费 SOG 本体图或 SOUL.md / 注意力数据 / Agent 任务日志。
 */

import type { IntentAlignment, AttentionAllocation } from './types';
import { computeAttention } from './attention-allocator';
import { extractIdentityMarkers } from './identity-extractor';
import { getBlueprintRecord } from '../../task-store';
import { createLogger } from '../../infra/logger';
import { getEngineContext } from '../../engine-context';
import { SOGNodeType, SOGEdgeType } from '../../sog/sog-core-schema';
import { createGraphStore } from './graph-store';
import type { GraphStore } from './graph-store';

const log = createLogger('engine-server/pipeline/diagnosis/intent-alignment');

